import json
from fractions import Fraction

# Two-digit numbers N = 10a + b with 1 <= a <= 9, 0 <= b <= 9.
# Condition: N / S == S / 3, where S = a + b is the digit sum (S != 0).
solutions = []
checked = 0
for n in range(10, 100):
    a, b = divmod(n, 10)
    s = a + b
    checked += 1
    if s == 0:
        continue
    if Fraction(n, s) == Fraction(s, 3):
        solutions.append({"number": n, "digit_sum": s,
                          "quotient": str(Fraction(n, s))})

if solutions:
    final = ", ".join(str(x["number"]) for x in solutions)
else:
    final = "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "method": "exhaustive enumeration of two-digit numbers with exact Fraction comparison",
        "candidates_checked": checked,
        "solutions": solutions,
    },
}))
